import {ozymandias} from './reading-texts09.js?v=20261028-lit09';
const A='https://filestore.aqa.org.uk/resources/english/AQA-8702-TG-POEMS.PDF';
const F=s=>`https://www.folger.edu/explore/shakespeares-works/macbeth/read/${s}/`;
const C='https://www.gutenberg.org/files/46/46-h/46-h.htm';
const W='https://www.nationalarchives.gov.uk/help-with-your-research/research-guides/poverty-poor-laws/';
const make=d=>{
 const unseen=d.topic==='unseen',topic=unseen?'unseen':'skills',id=`lit.${topic}.${d.key}`,full=!!d.textKeys?.length;
 const qs=(stage,rows)=>rows.map(([prompt,correct,a,b,why,concept],i)=>{const answer=(i+d.key.length)%3,options=[a,b];options.splice(answer,0,correct);return{id:`${id}.${stage}.${i+1}`,prompt,options,answer,why,concept:`${id}.${concept}`};});
 const sources=[...new Set([...(d.textKeys||[]).map(k=>readings13[k].url),...(d.sources||[])])];
 return{id,topicId:`english-literature.${unseen?'unseen':'reading-writing'}`,title:d.title,scope:d.scope,minutes:d.minutes||30,refs:unseen?['3.2.3','3.3']:['3.3'],author:d.author||(full?(d.textKeys.length===1?readings13[d.textKeys[0]].author:'Selected poets'):'William Shakespeare'),rights:d.original?'original_teaching':'public_domain',textType:full?'poem':d.original?'prose':d.textType||'play',textTitle:full?d.textKeys.map(k=>readings13[k].title).join(' / '):d.textTitle||'Macbeth',readingURL:sources[0],checked:'29 October 2026',sources,contextReading:sources.map(url=>({url,label:Object.values(readings13).find(r=>r.url===url)?.title|| (url===C?'A Christmas Carol · complete text':url===W?'National Archives · poor law context':url===A?'AQA assigned anthology':'Assigned primary source')})),sourceNote:d.sourceNote||(full?d.textKeys.map(k=>`${readings13[k].title} — ${readings13[k].author}. ${readings13[k].note}`).join(' ')+' Original unfamiliar-reading practice, not a set poem or official question. Prior familiarity makes a later attempt revision rather than genuinely unseen reading.':'Short underlying public-domain textual evidence with original teaching commentary. Read the linked whole scene or stave. Interpretations require evidence and may differ; quotations and original practice writing have distinct labels.'),explorerNote:d.explorerNote||(full?'Complete public-domain poem text; original commentary and glosses. Sources and editions in Sources & notes.':undefined),cards:d.cards,views:[{kind:'language',label:full?'Read the poem'+(d.textKeys.length>1?'s':''):'Evidence decisions',title:full?'Read the complete text'+(d.textKeys.length>1?'s':''):d.scope,content:full?whole13(...d.textKeys):d.quote,words:d.details,readingRegion:true,...(full?{fullText:true}:{}),...(d.original?{originalSummary:true,textType:'prose'}:{})},{kind:'people',label:'Compare perspectives',title:'Test the positions',rows:d.people},{kind:'timeline',label:'Develop the argument',title:'Trace the reasoning',events:d.movement}],tasks:[[d.challenge[0],d.challenge.slice(1,4),0,d.challenge[4],d.challenge[5]]],practice:qs('practice',d.practice),check:qs('check',d.check),writing:d.writing,rubric:d.rubric,...(d.extra||{})};
};
export const batch13=[
make({topic:'unseen',key:'workshop-02',title:'Unseen imagery and connotations workshop',scope:'The Eagle · scale and apparent agency',textKeys:['eagle'],
cards:[['Locate the literal scene before extending it','Read all six lines: an eagle stands high above a sea and then falls or descends with sudden force. Crag means a steep rock; azure means blue. The description gives a viewpoint and a movement, but does not establish every detail of a hunt or make the bird literally a human ruler.'],['Explain a relation within the imagery','Hands gives the bird a humanised grip, while the sea seems small and wrinkled from its height. The thunderbolt comparison changes stillness into a sudden, forceful descent. Analyse what each relation contributes to scale and apparent power rather than simply naming personification or simile as if a label supplied the meaning.'],['Test the limit of the apparent control','The poised first stanza can suggest command, while the final movement may emphasise force, speed or a break in stillness. Use the actual syntax and image to defend a reading. The poem does not report a political motive or guarantee a particular prey; apparent agency is something the language constructs.']],details:[['crooked hands','Humanised grip shapes apparent agency without making the eagle literally human.'],['wrinkled sea','The viewpoint makes a vast surface appear small and textured. Azure: blue; crag: steep rock.'],['thunderbolt','The comparison gives the final descent sudden force rather than proving a literal lightning strike.']],people:[['Eagle represented','Is placed in height, stillness and sudden movement.'],['Descriptive voice','Shapes scale through selected comparisons.'],['Reader','Tests apparent power against the short whole poem.']],movement:[['Locate','Clarify the literal scene and vocabulary.'],['Analyse','Connect an image with scale or agency.'],['Turn','Read the change from standing to descent.'],['Qualify','Keep suggested power distinct from an invented motive.']],challenge:['Which reading respects figurative imagery?','Humanised hands can suggest grip and control without making the bird a literal human ruler.','The eagle is confirmed to govern a human kingdom.','Thunderbolt proves a literal lightning strike killed the bird.','A comparison creates a relation rather than establishing physical identity.','Explain the image without extending it into an unsupported event.'],practice:[['Why establish the viewpoint?','It explains how the sea can appear wrinkled beneath the bird.','It proves the sea is physically tiny.','It supplies an exact map of the poet’s travels.','Scale is shaped by the position presented in the description.','perspective'],['What does the final comparison add?','Sudden force to a movement after stillness.','A guarantee of a named prey and its fate.','Proof that every simile has the same emotion.','Interpret a comparison through its position and local action.','methods'],['Which inference exceeds the evidence?','The bird has a verified human political motive.','The description can suggest control.','The poem changes from stillness to movement.','Apparent agency is not a complete account of intention.','limits']],check:[['What happens across the two stanzas?','A poised position is followed by a forceful descent.','A ruler delivers a political speech to the sea.','The poem names the precise prey captured.','Begin with the action actually presented.','meaning'],['What does azure mean?','Blue.','Angry.','A human crown.','Clarifying vocabulary supports the literal scene.','vocabulary'],['How should hands be analysed?','As a humanising choice shaping an impression of grip.','As proof the bird has literally become a person.','As an automatic diagnosis of a poet’s beliefs.','Figurative choices create possibilities to test.','methods'],['What makes a judgment qualified?','Use scale and movement to discuss power without inventing motive or outcome.','State a detailed hunting story absent from the poem.','Treat a method label as a complete interpretation.','The strength of a reading depends on its evidence and limits.','argument']],writing:'How does Tennyson make the eagle seem powerful? Analyse scale and the turn from stillness to movement, qualifying what the poem does not establish.',rubric:['Establish a secure literal account and clarify unfamiliar vocabulary.','Explain the local work of two precise images rather than list labels.','Use the whole poem while distinguishing suggested agency from invented motive.']}),
make({topic:'unseen',key:'workshop-03',title:'Unseen stanza movement and turns workshop',scope:'The Tropics in New York · seeing, memory and longing',textKeys:['tropics'],
cards:[['Read the whole movement, not only the fruit','The opening catalogue places fruit in a window; the next stanza moves into remembered landscape, and the final stanza presents a bodily response of longing. Rills are small streams; benediction means blessing. A reading of cheerful abundance alone misses the turn towards a painful relation between the present and remembered home.'],['Explain what the stanza boundaries organise','The shift from things seen to memories and then tears gives the images a developing function. The catalogue can stimulate an experience that becomes difficult to sustain. Explain how a boundary changes attention and feeling rather than assuming every new stanza merely starts an unrelated idea.'],['Keep memory and biography distinct','The speaker’s longing makes the remembered place significant, but the poem is not a complete factual map or an unrestricted biography of McKay. Analyse how the voice presents distance and attachment through a particular detail. A qualified judgment can recognise loss without claiming to know every cause of the speaker’s situation.']],details:[['Set in the window','A present sight becomes the trigger for memory.'],['bringing memories','The syntax connects objects with a different place and time. Rills: streams; benediction: blessing.'],['wave of longing','A bodily metaphor makes the remembered connection emotionally forceful.']],people:[['Present observer','Encounters a display in a different location.'],['Remembering voice','Reconstructs a place through selected sensory images.'],['Reader','Follows the transition without assuming complete biographical knowledge.']],movement:[['See','Identify the present display.'],['Remember','Trace the shift into landscape.'],['Respond','Read the bodily and emotional turn.'],['Judge','Explain the movement from abundance to longing.']],challenge:['Which reading accounts for the whole poem?','An attractive display triggers memory that develops into painful longing.','The catalogue proves the voice remains cheerful without change.','Every image is an independently verified geographical survey.','The final response changes how the earlier abundance is understood.','Follow the later turn rather than stopping at the opening objects.'],practice:[['What triggers the memories?','Fruit encountered in a window display.','A detailed account of the speaker’s entire childhood.','An official map quoted by the narrator.','The present sight provides a concrete point of departure.','meaning'],['What makes a stanza point analytical?','Explain how the boundary redirects attention from sight to memory or response.','Only count three stanzas and stop.','Assume every stanza has an identical function.','Organisation needs a relation to developing meaning.','methods'],['Which biographical claim needs qualification?','The poem gives a complete explanation of every cause of McKay’s life choices.','A speaker can experience longing.','A remembered landscape can be emotionally significant.','The presented voice is not complete biographical evidence.','limits']],check:[['Which sequence is accurate?','Display, remembered landscape, then a response of longing.','A constant cheerful catalogue with no emotional turn.','A political proclamation followed by a literal map.','The organisation develops the relation between sight and feeling.','meaning'],['How can the final stanza affect the opening?','It makes abundance part of an experience of distance and loss.','It erases every earlier image from significance.','It proves all memories are false.','A later turn can revise an earlier impression.','structure'],['What does rills mean?','Small streams.','Public ceremonies.','Dangerous storms.','Vocabulary clarifies the remembered landscape.','vocabulary'],['What supports a proportionate interpretation?','Analyse the movement and an image while qualifying biography and causes.','Invent a complete travel history from the title.','Ignore the tears to preserve a cheerful thesis.','A whole-poem account responds to both support and complication.','argument']],writing:'How does the poem turn a display of abundance into an experience of longing? Analyse stanza movement and one sensory image, distinguishing memory from complete biography.',rubric:['Trace the whole sequence from present sight through memory to response.','Explain a stanza boundary and a precise image as developing methods.','Qualify claims about biography, geography and the causes of longing.']}),
make({topic:'unseen',key:'workshop-04',title:'Unseen rhythm sound and sentence movement',scope:'The Swing · repeated motion and a changing view',textKeys:['swing'],
cards:[['Hear movement through the actual words','Read the complete poem aloud or silently attend to its repeated upward and downward phrases. The voice presents enjoyment and changing views through a swing’s motion. A sound observation should identify a real repetition or rhythm rather than rely on a rule that every regular pattern must express one fixed emotion.'],['Follow syntax across the view','The clauses move over a wall, across countryside and down towards a garden and roof before rising again. Explain how repeated directional words and sentence movement organise the reader’s attention. Counting rhyme alone would miss the relation between the pattern and the described oscillation.'],['Keep a constructed voice distinct from a diary','The childlike speaking position invites a response to the changing scene, but it is not proof that every line records Stevenson’s exact personal memory. A qualified interpretation can explain how sound and viewpoint present pleasure without promising that all readers experience the same feeling or imagining an event the poem never describes.']],details:[['Up in the air','Repetition returns attention to an upward movement.'],['Till / Till','Continuing clauses organise successive changes in the view.'],['up … down','A final directional relation completes an oscillation rather than a one-way journey.']],people:[['Enjoying speaker','Presents a particular relation to the repeated motion.'],['Implied listener','Is addressed through the opening question.'],['Reader','Tests how sound and syntax shape the changing view.']],movement:[['Hear','Locate a repeated directional phrase.'],['Follow','Trace the successive views through clauses.'],['Return','Read the renewed rise and descent.'],['Explain','Connect the verbal pattern with the motion presented.']],challenge:['Which sound claim is evidence-led?','Repeated directional phrases and clauses shape the sense of rising, looking and returning.','Every regular rhythm always proves happiness in any poem.','A rhyme count by itself explains every image.','Sound needs to be related to the local experience and syntax.','Locate what repeats and what the repetition does here.'],practice:[['What does the viewpoint do?','It changes as the speaker rises and looks down.','It remains a complete stationary map throughout.','It supplies a literal biography of every child.','The described motion organises what becomes visible.','perspective'],['Why examine clauses as well as rhyme?','They connect successive views and changes of direction.','Syntax is irrelevant once a rhyme is present.','Every sentence must remain inside one printed line.','Sound and sentence movement can work together.','methods'],['Which claim overstates autobiography?','The constructed childlike voice verifies Stevenson’s exact personal experience.','A poem can present enjoyment.','Repeated phrases can organise movement.','A speaking position is not automatically a complete diary.','limits']],check:[['What kind of movement develops?','Repeated rising and falling with changing views.','A single journey with no return.','A static scene without any addressed listener.','Track the recurring action in the whole text.','meaning'],['What should a rhythm analysis explain?','The relation between an actual pattern and the motion presented.','A universal emotion attached to every regular beat.','Only a label with no evidence in the words.','A local relation makes the observation analytical.','methods'],['Which feature organises attention?','Continuing clauses directing the view over and down.','An invented stanza about a later accident.','A fixed rule that every rhyme means the same thing.','Use the sequence that is actually present.','structure'],['Which conclusion is qualified?','The voice constructs pleasure through motion without verifying exact autobiography.','Every reader must feel identical joy.','The poet literally speaks as every child who has used a swing.','Distinguish a presented experience from universal or biographical claims.','argument']],writing:'How do sound and sentence movement present the experience of swinging? Analyse repetition and the changing view, keeping the speaking voice distinct from biography.',rubric:['Locate a real repeated pattern and explain its local work.','Connect syntax and viewpoint with the development of movement.','Qualify effects and distinguish a constructed voice from verified autobiography.']}),
make({topic:'unseen',key:'workshop-05',title:'Unseen ambiguity and alternative interpretations',scope:'Spellbound · inability, refusal and threat',textKeys:['spell'],
cards:[['Begin with what is explicit','The voice faces darkening weather, bending trees and a descending storm while repeatedly stating an inability to go. Drear means bleak or gloomy; wastes suggests expanses of barren land. The poem does not identify every cause of the binding force, so begin with the stated position rather than inventing a supernatural backstory.'],['Test a tension rather than choose a label first','The last line combines will not with cannot. A reading of powerlessness must account for refusal; a reading of defiance must account for repeated inability and threat. Present the strongest evidence for each instead of reducing the poem to either total freedom or a fully explained external spell.'],['Make the judgment proportionate','The repeated endings and enlarging landscape can intensify a constrained or resistant position. Use the tension to refine your interpretation without claiming every alternative is equally supported. An unresolved cause is not permission to invent a biography or a particular event beyond the words.']],details:[['cannot, cannot','Repetition foregrounds a limit on movement.'],['Clouds beyond clouds','An accumulating landscape extends the sense of surrounding space. Wastes: barren expanses; drear: gloomy.'],['will not, cannot','Refusal and inability coexist and need to be considered together.']],people:[['Constrained voice','States inability within a threatening landscape.'],['Defiant reading','Tests the significance of refusal in the ending.'],['Critical reader','Weighs both accounts without inventing an explanation.']],movement:[['Locate','Establish the explicit constraint.'],['Support','Find evidence for inability.'],['Challenge','Test the final refusal against that reading.'],['Qualify','Explain what remains unresolved.']],challenge:['Which judgment handles the ending’s tension?','The voice combines refusal with inability, complicating a simple account of either freedom or helplessness.','The exact identity of a magician is confirmed.','Will not proves there is no constraint anywhere.','A strong reading accounts for language that complicates its first claim.','Read both parts of the final statement together.'],practice:[['What should be established before speculation?','The explicit threatening scene and repeated inability to go.','A complete invented supernatural plot.','The poet’s entire biography as fact.','Literal grounding limits unsupported inference.','meaning'],['What tests a pure helplessness reading?','The addition of will not in the final line.','The number of letters in the title.','An invented rescue after the ending.','Relevant counter-evidence can refine a claim.','alternatives'],['Why not accept every interpretation equally?','Each needs to explain the actual wording and its tensions.','Ambiguity makes evidence unnecessary.','A different claim is automatically correct.','Uncertainty does not remove standards of support.','evaluation']],check:[['What remains unconfirmed?','The complete cause or identity behind the binding force.','The repeated statement of inability.','The presence of threatening weather.','Distinguish explicit wording from explanatory speculation.','meaning'],['What is important about will not, cannot?','It combines resistance with a statement of limitation.','It proves unqualified freedom and no threat.','It names a particular rescuer.','The juxtaposition creates a tension to explain.','methods'],['How should an alternative be tested?','Use its strongest relevant evidence and a detail that challenges it.','Invent a weak rival with false quotation.','Ignore every detail that causes difficulty.','A fair test improves the precision of judgment.','evaluation'],['Which conclusion is proportionate?','Constraint and refusal remain in tension without a fully confirmed backstory.','One interpretation supplies a complete verified biography.','No evidence can matter because the poem is ambiguous.','A qualified account can retain unresolved causes and still make an argument.','argument']],writing:'How far does the voice appear powerless or resistant? Defend two readings through precise language and reach a qualified judgment that accounts for the ending.',rubric:['Establish explicit situation and vocabulary before extending inference.','Test powerlessness and refusal through genuine evidence in the poem.','Reach a qualified judgment without inventing causes or accepting unsupported claims.']}),
make({topic:'unseen',key:'workshop-06',title:'Unseen comparative claim and evidence workshop',scope:'The Eagle / The Swing · height, perception and motion',textKeys:['eagle','swing'],
cards:[['Frame a shared question with a difference','Both poems connect height with a view and a movement, but their speaking positions differ. The eagle is described from outside, while the swing voice presents an addressed experience of enjoyment. Begin with how height shapes perspective rather than assuming every upward image carries identical power or emotion.'],['Pair methods that can actually be related','Compare a particular image of the view below with a repeated or sudden movement. Explain what the method allows a reader to perceive in each text. A comparative sentence should do more than announce similarly: it needs the reasoning that makes the similarity or difference relevant to the focus.'],['Test the comparative claim against the whole texts','The eagle’s stillness and sudden descent differ from the swing’s recurring oscillation. Use that structural contrast to qualify an initial shared claim about freedom or control. Do not make the eagle speak the child’s words or infer a shared literal biography merely because both poems describe height.']],details:[['View below','Compare the selected details made visible by height.'],['Sudden / recurring','Distinguish a forceful change from repeated oscillation.'],['Outside / speaking position','Explain how different voices shape access to the experience.']],people:[['Described eagle','Is presented through an external descriptive voice.'],['Swing speaker','Addresses a listener about an enjoyable motion.'],['Comparing writer','Builds a relation without collapsing the positions.']],movement:[['Focus','Ask how height shapes perception.'],['Pair','Choose a method in each whole poem.'],['Contrast','Explain sudden versus recurring movement.'],['Judge','Qualify the shared claim through a significant difference.']],challenge:['Which comparison explains a real relation?','Height shapes both views, but a sudden descent differs from the swing’s recurring movement.','Both poems necessarily use the same first-person narrator.','Every upward image guarantees identical freedom.','Comparison can preserve a shared focus and a significant structural difference.','Relate the methods without making the situations identical.'],practice:[['What should a comparative claim contain?','A relevant relation supported by methods in both texts.','Only two titles joined by and.','An invented identical narrator.','A relation needs evidence and interpretive purpose.','comparison'],['Why compare the movements?','Sudden descent and repeated oscillation develop different experiences.','They prove the poems cannot share any focus.','All movement in poetry means exactly the same thing.','A structural difference can sharpen the shared question.','methods'],['Which inference is unsafe?','Height makes both speakers and situations identical.','Both texts can shape a view from above.','Voice affects how a reader accesses the scene.','Shared imagery does not remove differences in presentation.','limits']],check:[['Which voice distinction is accurate?','An externally described eagle differs from the swing’s speaking position.','Both poems are spoken by the eagle.','Every first-person child voice is Tennyson’s diary.','Attribution keeps the comparison accurate.','meaning'],['What makes a paired detail useful?','Its method helps answer the same focus in a different way.','It is long enough to fill the paragraph.','It has no explained relation to the question.','Relevance matters more than quotation quantity.','evidence'],['How can structure qualify freedom?','A single sudden movement differs from a repeating rise and fall.','All movement guarantees the same kind of control.','The endings have no relevance to the opening claim.','Development can test a simple shared label.','structure'],['What makes a conclusion comparative?','Explain what the differing views and movements show about the shared focus.','Retell each poem separately without a relation.','Only repeat that the poems mention height.','A judgment must use the relationship already analysed.','argument']],writing:'Compare how height and movement shape the experiences presented. Analyse a precise method in each poem and develop a significant difference in voice or organisation.',rubric:['Sustain a shared question supported by evidence from both complete poems.','Explain a precise relational difference in voice, perception or movement.','Use the whole texts to qualify rather than force a common label.']}),
make({topic:'unseen',key:'workshop-07',title:'Timed unfamiliar poem analysis assessment',scope:'Guided Eagle · fresh independent sonnet',textKeys:['eagle'],minutes:45,sources:[readings13.fears.url],
cards:[['Transfer the method, not the interpretation','Use The Eagle to practise a secure literal account, a precise image and a whole-poem turn. A different poem will need its own evidence. Do not carry a claim about powerful descent into a new text merely because it worked in the teaching example; first read what the fresh voice actually presents.'],['Build a whole-poem line of reasoning','A plan should connect an opening position, a development and a significant ending through methods. Close reading is more than collecting devices, while whole-poem attention is more than retelling events. Keep an alternative or qualification where the evidence resists your first impression.'],['Preserve the unfamiliar attempt before support','The independent workspace supplies a different complete poem. Aim for about 35 minutes, advisory rather than enforced. Guidance and review criteria remain hidden until the first submission, which is preserved separately from revisions. If you already know the poem, treat the task as practice or retrieval rather than claiming it was genuinely unseen.']],details:[['Literal account','Establish what the new voice actually presents.'],['Method and development','Explain a precise choice through the whole poem’s movement.'],['First response','Keep independent performance separate from supported revision.']],people:[['Preparing reader','Practises a transferable method on a known text.'],['Independent writer','Builds a new argument from the supplied unfamiliar poem.'],['Later reviewer','Examines the preserved response without inventing a mark.']],movement:[['Read','Establish the fresh situation and vocabulary.'],['Plan','Select a relevant route through the whole poem.'],['Write','Explain choices that support the actual claim.'],['Check','Review accuracy and qualification before submission.']],challenge:['Which preparation transfers responsibly?','Use the method of literal grounding and close analysis, then adapt the claim to the fresh poem.','Reuse the Eagle interpretation without reading the new text.','List device names instead of developing a response.','A method transfers through a new evidence-led application.','Check what the fresh voice actually states before choosing a claim.'],practice:[['What does whole-poem attention include?','A relation between the opening, development and ending.','Only the first image with every later turn ignored.','A list of all words without a claim.','An interpretation should account for change across the text.','structure'],['What should a precise method point do?','Explain how a choice supports the interpretation in context.','Replace evidence with a familiar technical label.','Assign one universal emotion to every punctuation mark.','A method observation needs local interpretive work.','methods'],['What happens after encountering the poem?','A later attempt is revision or retrieval rather than guaranteed unfamiliar reading.','The poem becomes an official AQA question.','Every future attempt is automatically genuinely unseen.','Familiarity must be described honestly.','conditions']],check:[['What should a fresh claim be based on?','The actual new poem’s language and development.','An unchanged interpretation copied from the teaching example.','A biography invented from the title.','Transfer requires a response to new evidence.','meaning'],['Which plan supports an argument?','Connect selected methods across the whole poem to the question.','Ignore the ending if it complicates the thesis.','Write a fixed list of device definitions.','A relevant route explains the relation of details.','planning'],['When are review criteria shown in the independent workspace?','After the first response has been submitted.','As answer-revealing hints before any attempt.','Only after an automatic official mark is awarded.','Independent and supported performance remain distinguishable.','assessment'],['What should editing prioritise?','Accurate evidence, clear sentences and a qualified answer to the question.','Invented quotations that make the thesis easier.','Extra length with no reasoned relation.','Checking should strengthen the response’s substance and expression.','editing']],writing:'Practise a short analysis route with The Eagle, then use the independent workspace for the different complete poem supplied there.',rubric:['Develop a supported interpretation of fear and possibility through the whole supplied poem.','Analyse precise language and the movement towards the ending.','Use accurate references and qualify what the voice does and does not establish.'],extra:{independentWriting:true,independentTaskType:'unseen-single',independentTaskLabel:'Original unfamiliar-poem practice with a complete supplied poem, not an official paper.',independentIntro:'Aim for about 35 minutes including planning and checking. Timing is advisory, not enforced. If you have encountered this poem before, describe the attempt as practice rather than genuinely unseen.',independentPrompt:'How does Keats present fear and possibility in When I have Fears That I May Cease to Be? Analyse language and the poem’s development, using the complete supplied text.',independentExtractLabel:'Complete public-domain poem · source and edition in lesson notes',independentExtract:whole13('fears')}}),
make({topic:'unseen',key:'workshop-08',title:'Timed unfamiliar poem comparison assessment',scope:'Guided height pair · fresh private-feeling pair',textKeys:['eagle','swing'],minutes:25,sources:[readings13.poison.url,readings13.dwelt.url],
cards:[['Prepare a comparison that preserves difference','Use the height pair to practise a shared focus and a significant difference. Explain how voices, images or movement shape a related experience. A comparison is not improved by claiming everything matches; the relation becomes more precise when it preserves what each text does differently.'],['Read both new poems before fixing the claim','The independent pair concerns a different focus, private feeling. Read both complete texts and choose a relevant method in each. Do not turn a similarity of subject into a claim of identical attitude or moral judgment, and keep the speaking voices distinct from their authors.'],['Use the short practice budget honestly','Aim for about 10 minutes for the independent comparison; timing is advisory, not enforced. This practises a focused comparison, not a full two-essay exercise. First submissions are preserved separately from revisions, and guidance stays hidden until submission. Prior knowledge of either poem changes the claim of unfamiliarity.']],details:[['Shared focus','A relation makes both texts relevant to one question.'],['Significant difference','Explain how a different method changes the response.'],['Fresh pair','Read new evidence instead of repeating the guided height argument.']],people:[['First poem voice','Presents its own relation to the shared focus.'],['Second poem voice','Needs analysis without being collapsed into the first.'],['Comparing writer','Connects methods and differences within the actual task.']],movement:[['Read both','Establish each voice’s position.'],['Relate','Choose a shared question supported by the texts.'],['Analyse','Compare a specific method in each.'],['Judge','Explain a significant difference within the short response.']],challenge:['Which plan is genuinely comparative?','Relate methods in both fresh poems to the shared focus while explaining a significant difference.','Write two unrelated summaries and add similarly.','Reuse the guided height claim without reading the new pair.','A comparison needs reasoning between the actual texts.','State what the relation explains rather than merely naming both titles.'],practice:[['Why read both texts before choosing the claim?','The evidence may complicate an expected similarity.','Every poem with a shared theme has an identical attitude.','The second title makes close reading unnecessary.','A relevant relation must be tested in both texts.','selection'],['What does a short comparison prioritise?','A focused method-level relation and an important difference.','A complete biography of both poets.','All remembered facts regardless of the question.','Selection matters within an advisory short budget.','planning'],['What remains unchanged after revision?','The preserved first submission.','An automatically assigned official essay mark.','Nothing, because the first response is silently deleted.','A record separates initial performance from supported change.','versions']],check:[['What supports the comparative claim?','Evidence and methods in both supplied texts.','Only an assumption that similar topics mean identical meanings.','An unchanged paragraph from a different pair.','The relation should be grounded in the actual poems.','meaning'],['What makes a difference useful?','It develops the shared question rather than forcing a match.','It proves comparison is impossible.','It removes the need to consider one poem.','A precise contrast can sharpen the argument.','comparison'],['Which speaker claim is unsafe?','Every poetic voice is a complete literal biography of its author.','Different voices can present different relations to feeling.','A reader can qualify an interpretation.','Constructed speaking positions need accurate attribution.','voice'],['What is the task’s status?','Original timed practice with an advisory budget, not an official paper.','An enforced exam with an automatic GCSE mark.','A guarantee neither text has ever been seen.','Describe conditions and evidence of performance honestly.','assessment']],writing:'Practise one comparative sentence with the guided height pair, then respond to the different private-feeling pair in the independent workspace.',rubric:['Compare how private feeling becomes significant in both supplied poems.','Analyse a precise method in each and develop a significant difference.','Use accurate references and keep the voices’ ethical or emotional positions distinct.'],extra:{independentWriting:true,independentTaskType:'unseen-pair',independentTaskLabel:'Original short unfamiliar-poem comparison with two complete supplied texts.',independentIntro:'Aim for about 10 minutes for a focused comparison. Timing is advisory, not enforced. If either poem is familiar, describe this as practice rather than a genuinely unseen encounter.',independentPrompt:'Compare how private feeling becomes significant in A Poison Tree and She Dwelt among the Untrodden Ways. Focus on methods and a significant difference; do not assume the voices make the same ethical judgment.',independentExtractLabel:'Two complete public-domain poems · no teaching interpretation supplied during the attempt',independentExtract:whole13('poison','dwelt')}}),
make({topic:'unseen',key:'workshop-09',title:'Feedback-led unseen revision and delayed transfer',scope:'First Fig · revise one response and transfer later',textKeys:['fig'],sources:[readings13.poison.url,readings13.dwelt.url],
cards:[['Diagnose a real comparative weakness','Bring the first pair assessment into this workshop if it is saved here. Review the single-poem assessment in its own workspace when needed. Use criteria and any real teacher feedback to locate one gap in evidence, method or the relation between texts. The app does not invent an examiner’s mark or pretend a feedback meeting has taken place.'],['Revise before testing a different text','Explain a method-level difference if the first comparison forces the two voices into an identical position. Save the revised version while preserving the original. First Fig supplies a separate transfer opportunity: a candle image presents limited duration alongside valued brightness. Foes means enemies; the image is not a literal instruction to burn a candle dangerously.'],['Return after an interval for delayed transfer','Read the new short poem now if useful, but an immediate attempt is not proof of delayed transfer. Return after time has passed, establish its explicit contrast and support a fresh interpretation before rereading these notes. Keep the speaker’s valuation distinct from universal advice, and verify remembered evidence against the source.']],details:[['both ends','The image presents intensity with limited duration, not a literal instruction.'],['will not last','The voice acknowledges a limit rather than denying consequences.'],['But … lovely light','The turn values brightness despite the limit; foes means enemies.']],people:[['First-response writer','Has evidence of an earlier attempt to revise.'],['Reviewing writer','Uses criteria and real feedback rather than invented marks.'],['Later transfer reader','Tests a method on a different text after an actual interval.']],movement:[['Diagnose','Identify a weakness in the earlier comparison.'],['Revise','Improve its use of evidence and relation.'],['Transfer','Read a different complete poem without importing a fixed claim.'],['Return later','Distinguish immediate familiarity from delayed evidence.']],challenge:['Which claim about transfer is honest?','A new text offers a transfer opportunity, but a delayed test requires a later return.','Opening a new poem immediately proves permanent transfer.','A saved version automatically establishes essay mastery.','The timing and the evidence must match the learning claim.','Separate an immediate opportunity from an actual delayed attempt.'],practice:[['What should guide the redraft?','A real gap in the writing, criteria or feedback actually received.','An invented examiner comment.','A random synonym change unrelated to reasoning.','Diagnosis needs evidence from the response being revised.','diagnosis'],['What contrast matters to First Fig?','Limited duration and the value assigned to brightness.','A guarantee the candle never burns out.','An official instruction to ignore every consequence.','The voice acknowledges a cost while making a valuation.','methods'],['What is needed for delayed transfer?','A later attempt after an interval on a different text or focus.','Immediate rereading declared permanent mastery.','A copied interpretation without new evidence.','A delayed claim requires a genuinely later opportunity.','transfer']],check:[['What does the bring-in action preserve?','The original first pair assessment remains unchanged.','Every source submission is overwritten.','The knowledge score becomes an official writing mark.','A copy into an empty draft keeps the records separate.','meaning'],['How should the candle image be interpreted?','As a figurative contrast between intensity, duration and value.','As compulsory literal safety advice.','As proof there are no limits or costs.','Explain the relation constructed by the image.','methods'],['What does foes mean?','Enemies.','Candles.','A calendar date.','Vocabulary helps establish the speaking situation.','vocabulary'],['Which conclusion is proportionate?','A version records revision; durable skill needs later evidence and human review.','Saving guarantees every future essay will succeed.','No revision can ever be useful.','Records of activity and evidence of attainment remain distinct.','review']],writing:'Bring in the first pair response if available, diagnose one real weakness and save a substantive revision. Return later to analyse First Fig as a separate transfer text; record when you actually attempt it.',rubric:['Use the actual response and real feedback if available to diagnose one weakness.','Strengthen the relation between methods and comparative interpretation.','Analyse the new poem through its own evidence and distinguish immediate from delayed transfer.'],extra:{revisionFrom:'lit.unseen.workshop-08'}}),
make({key:'workshop-01',title:'Vocabulary in context and difficult syntax',scope:'Macbeth 1.7 · duties, clauses and qualification',sources:[F('1/7')],quote:'He’s here in double trust:\nFirst, as I am his kinsman and his subject,\nStrong both against the deed; then, as his host,',
cards:[['Find the sentence’s relationships','Macbeth lists relationships to Duncan that count against the proposed deed. Identify who he refers to and how First and then organise the reasons. Difficult syntax becomes more manageable when you trace subject, action and qualification, rather than replacing each unfamiliar word with an isolated modern synonym.'],['Use context to choose a meaning','Trust concerns obligations within kinship, political allegiance and hospitality in this passage. A dictionary can offer possibilities, but the surrounding clauses decide which sense is relevant. Do not flatten double trust into a simple claim that Duncan is gullible or that Macbeth has already fulfilled every duty he recognises.'],['Preserve qualification in an explanation','An accurate account keeps the reasons against the deed visible before drawing an inference about conflict or responsibility. Explain how the enumerated syntax makes obligations accumulate. Recognising an obligation is not the same as obeying it; the wider scene and subsequent conduct test that distinction.']],details:[['double trust','Read obligations through the relationships that follow.'],['First / then','The syntax organises cumulative reasons against the deed.'],['as his host','A social role creates a further duty within the immediate situation.']],people:[['Macbeth','Names obligations while considering an action against them.'],['Duncan','Is described through kinship, allegiance and hospitality.'],['Critical reader','Traces the syntax before judging recognition and conduct.']],movement:[['Resolve','Identify pronouns and the proposed deed.'],['Organise','Follow the list of relationships.'],['Interpret','Choose a contextual sense for trust.'],['Qualify','Separate recognition of duty from obedience.']],challenge:['Which explanation preserves the syntax?','The listed relationships accumulate reasons against the deed Macbeth considers.','The list proves Macbeth has already obeyed every obligation.','Trust only means Duncan is foolish in every possible context.','Context and clause relations determine the meaning of the passage.','Follow the reasons and their direction before extending a judgment.'],practice:[['What do First and then help organise?','A sequence of relationships supporting reasons against the deed.','Two unrelated future battles.','An exact date of Duncan’s death.','Connect the markers with the clauses they arrange.','syntax'],['How should a dictionary sense be chosen?','Test it against the surrounding relationships and argument.','Pick the first synonym without reading the sentence.','Change the source wording until the thesis fits.','Context constrains which possible meaning is relevant.','vocabulary'],['Which inference overstates recognition?','Naming a duty proves it has already been fulfilled.','Macbeth can recognise reasons against an act.','A role can create an obligation.','Recognition and conduct need separate evidence.','limits']],check:[['What is the direction of the listed reasons?','They count against the proposed deed.','They establish a duty to murder every guest.','They refer only to an unrelated scene.','Secure the sentence’s argument before interpreting conflict.','meaning'],['What supports the sense of trust here?','The kinship, subject and host relationships in the clauses.','An isolated synonym with no local relation.','The length of the word alone.','Context gives a vocabulary choice its appropriate scope.','vocabulary'],['What should a paraphrase retain?','The cumulative obligations and their opposition to the deed.','Only the word trust with all relationships removed.','An invented claim that the duty is already fulfilled.','A meaning account must preserve the passage’s logic.','syntax'],['What develops analysis beyond clarification?','Explain how enumeration makes competing obligations explicit.','Replace the whole passage with an unrelated definition.','Assume a difficult sentence has no interpretable structure.','Clarification enables an explanation of the writer’s choice.','argument']],writing:'Clarify the pronouns and clause relationships, then explain how the syntax presents Macbeth’s recognition of duties. Keep recognition distinct from conduct.',rubric:['Resolve pronouns, vocabulary and clause relations through the local context.','Preserve the direction and qualification of the argument in paraphrase.','Explain how syntax supports a claim rather than stopping at a synonym list.']}),
make({key:'workshop-02',title:'Accurate paraphrase without replacing analysis',scope:'Macbeth 1.4 · concealment and a private wish',sources:[F('1/4')],quote:'Stars, hide your fires;\nLet not light see my black and deep desires.',
cards:[['State the meaning honestly','A plain paraphrase could say that Macbeth wishes his private desires to remain concealed. It should be presented as your own account, not placed in quotation marks as if Shakespeare wrote it. Do not add a detailed plan or an outcome that the brief passage does not itself establish.'],['Explain the choice after clarifying it','Paraphrase helps secure meaning, but analysis asks how commands and imagined observation shape concealment. Choose a precise word or relation and explain what it contributes. Simply replacing the passage with a longer modern sentence does not establish the significance of the poet’s language.'],['Keep the reference in its situation','The aside follows the naming of Malcolm as successor and contrasts with a public performance of loyalty. That context gives the wish a dramatic position. Use it to develop a qualified argument about private desire, while avoiding the claim that a figurative address to stars makes the natural world literally obey Macbeth.']],details:[['hide','An imperative makes concealment something the speaker wishes to command.'],['light see','Imagined observation makes exposure part of the wish.'],['deep desires','The private position is distinguished from public presentation.']],people:[['Macbeth in private speech','Expresses a wish distinct from public loyalty.'],['Audience','Hears an aside rather than a public announcement.'],['Analytical writer','Uses paraphrase to ground, then explain, a precise choice.']],movement:[['Clarify','Give an accurate account in your own words.'],['Attribute','Keep paraphrase separate from exact quotation.'],['Analyse','Explain a specific choice in the source wording.'],['Locate','Connect the aside with its dramatic position.']],challenge:['Which response goes beyond paraphrase?','After clarifying the wish, explain how the imperative makes concealment an attempted command.','Retell the meaning at greater length and call it analysis.','Invent modern wording and put it in Shakespeare’s quotation marks.','Analysis explains a choice rather than merely translating the content.','Identify what the actual wording does in this situation.'],practice:[['What is honest paraphrase?','An accurate account in your own words without false quotation marks.','Invented source wording labelled exact.','A claim unrelated to the passage’s meaning.','Meaning can be clarified without pretending your sentence is the original.','accuracy'],['What should follow a meaning account?','Explain a precise source choice and its significance.','Only another longer translation of the same idea.','A guaranteed literal account of obedient stars.','Clarification is a basis for analysis, not a substitute for it.','methods'],['Why locate the aside?','Its position contrasts private desire with public loyalty.','It proves Duncan hears every private word.','It removes the need to consider audience knowledge.','Dramatic situation affects how the words function.','context']],check:[['Which meaning is supported?','Macbeth wishes his private desires to remain concealed.','A named star promises to carry out a complete murder plan.','The speech is a public confession to Duncan.','Keep literal meaning and speculative addition distinct.','meaning'],['What makes the imperative worth analysing?','It presents concealment as a command directed towards the imagined environment.','Every imperative always has an identical effect.','A grammar label supplies the full argument by itself.','A term needs a local account of its function.','methods'],['Which quotation practice is inaccurate?','Put your invented paraphrase in marks as Shakespeare’s exact words.','Label an accurate account as paraphrase.','Use a short verified phrase with explanation.','Your wording and the source’s wording have different statuses.','accuracy'],['What makes a developed paragraph?','Clarify meaning, analyse wording and connect it to the aside’s position.','Only translate the quotation into more words.','Ignore the original wording after naming the theme.','The steps should support a coherent evidence-led claim.','argument']],writing:'Paraphrase the wish accurately, then analyse two precise source choices and connect them with the aside’s dramatic position.',rubric:['Keep accurate paraphrase visibly distinct from exact source wording.','Explain a local choice rather than replace analysis with translation.','Connect the private wish to the dramatic situation with a qualified claim.']}),
make({key:'workshop-03',title:'Integrating short quotations and precise references',scope:'Macbeth 1.7 · evidence within a sentence',sources:[F('1/7')],quote:'I have no spur\nTo prick the sides of my intent, but only\nVaulting ambition',
cards:[['Choose the words the claim needs','A paragraph about recognised motive may need only the short phrase vaulting ambition, with the speaker and situation established. Longer quotation is not automatically stronger evidence. Select words whose exact form matters to your explanation, and do not shorten the passage so that its qualification or direction is reversed.'],['Make the grammar carry the reference','Integrate a short verified quotation within your own sentence and then explain its role. For example, Macbeth identifies ambition after considering reasons against the deed. Keep the quoted wording intact while making your surrounding grammar clear; do not silently rewrite Shakespeare to repair an awkward sentence.'],['Develop significance after integration','The riding image can frame ambition as a force tending beyond control, but recognising it does not prove Macbeth has overcome it. Use a wider action to test the claim. A neat embedded quotation serves an argument only when its relation to the interpretation is made explicit.']],details:[['no spur','A negative begins the consideration of motive.'],['but only','The qualification narrows the stated impulse.'],['Vaulting ambition','The figurative phrase needs explanation within the recognised motive.']],people:[['Macbeth','Names a motive during deliberation.'],['Quoting writer','Selects and attributes only the wording needed.'],['Critical reviewer','Checks accuracy, grammar and the explanatory relation.']],movement:[['Select','Choose a short phrase relevant to the claim.'],['Verify','Check words, attribution and qualification.'],['Integrate','Make your own grammar carry the reference.'],['Explain','Relate the wording to the argument and wider conduct.']],challenge:['Which quotation practice is strongest?','Select a verified short phrase and explain its function within a relevant claim.','Copy a long passage without explaining any words.','Change a qualification silently to make the claim easier.','Evidence quality depends on accuracy and argumentative work rather than length.','Ask why these exact words are needed for this claim.'],practice:[['When is a short quotation useful?','When its exact words help develop the claim.','Only when every surrounding word is omitted regardless of meaning.','Whenever length replaces the need for explanation.','Selection should preserve meaning and serve reasoning.','selection'],['What should remain unchanged inside quotation marks?','The verified source wording, apart from clearly signalled conventions.','Any words the writer wants to improve silently.','The speaker’s identity whenever attribution is inconvenient.','Your sentence must not falsify the source.','accuracy'],['What should follow integration?','Explain how the selected wording supports or qualifies the claim.','Only another unrelated quotation.','A prediction that neat grammar guarantees a top grade.','An embedded reference still needs interpretive work.','methods']],check:[['What does but only contribute?','It narrows the impulse Macbeth identifies.','It confirms that no motive is being considered.','It refers to a completely unrelated battle.','Retain the qualification when selecting evidence.','meaning'],['Which reference practice is inaccurate?','Silently change the quoted words to fit your grammar.','Use a short verified phrase in a clear sentence.','Identify the speaker and situation before analysis.','Surrounding expression should adapt to evidence, not falsify it.','accuracy'],['What makes the riding image analytical evidence?','Explain its relation to ambition and the limits of recognition.','Name metaphor and stop without a claim.','Treat it as a literal lesson in horse riding.','A method needs an account of significance in context.','methods'],['Which judgment is qualified?','Macbeth recognises ambition, but later conduct tests whether recognition limits it.','Naming the motive proves it has already been overcome.','Accurate quotation automatically establishes every interpretation.','Evidence can support recognition without proving a cure.','argument']],writing:'Integrate a short verified phrase into a claim about recognised motive. Analyse its image and qualify the judgment through a relevant later action.',rubric:['Select and attribute short evidence without dropping a necessary qualification.','Integrate verified wording into controlled grammar without silently altering it.','Explain the phrase’s significance and test the claim through wider conduct.']}),
make({key:'workshop-04',title:'Explaining significance beyond a device label',scope:'Ozymandias · a boast within a ruined setting',sources:[A],author:'Percy Bysshe Shelley',textTitle:'Ozymandias',textType:'poem',quote:'Nothing beside remains. Round the decay\nOf that colossal wreck, boundless and bare,',
cards:[['Identify a relation the detail creates','The ruined setting follows the ruler’s boast. Start with the relation between the asserted greatness and what the framing account presents as surviving. Naming imagery or contrast is only the beginning; explain which expectations the detail tests and why that matters to a claim about authority.'],['Make the method serve a question','For a question about enduring power, the scope of Nothing and the surrounding emptiness can test an attempt to control future judgment. A different question may require different emphasis. Do not write a fixed device sentence that could apply to any poem without changing a word.'],['Keep the effect within evidence','A reader may see the boast undermined while the representation of the ruler still survives in a mediated account. The ruin does not prove power never had consequences. A developed method point can explain a limit to endurance without making the unsupported claim that everything has vanished from history.']],details:[['Nothing beside','The scope tests the claim made in the inscription.'],['colossal wreck','Scale and damage coexist within the same description.'],['boundless and bare','The setting gives the damaged representation a wider frame.']],people:[['Ruler’s claim','Attempts to establish enduring status.'],['Framing account','Places that claim beside a different surviving scene.'],['Analytical reader','Explains the tension without denying all historical consequences.']],movement:[['Locate','Name the detail and the claim it follows.'],['Relate','Explain the tension between boast and setting.'],['Focus','Connect the relation with the actual question.'],['Qualify','State what the evidence does and does not establish.']],challenge:['Which point explains significance?','The ruined setting tests the boast’s claim to enduring greatness.','The poem uses imagery, so the analysis is complete.','A method label guarantees all readers reach one identical verdict.','Significance comes from an explained relation between a choice and the argument.','Say what the choice changes or challenges in this passage.'],practice:[['What should follow a device name?','An account of its local function and relevance to the claim.','Another list of terms with no interpretation.','A universal effect copied into every paragraph.','Terminology supports reasoning rather than replacing it.','methods'],['Why connect the point to the question?','The same detail can serve different emphases, and relevance needs explanation.','Every question asks exactly the same thing.','The title supplies all necessary reasoning.','An analysis point must do work for this task.','focus'],['Which conclusion overstates the ruin?','Power has never had any consequences at all.','The setting can undermine a claim of endurance.','A representation can survive as a damaged object.','A limit to permanence is not an absence of every effect.','limits']],check:[['What relation is central to these lines?','A damaged surviving scene tests a boast of greatness.','The ruler’s whole kingdom is shown intact and unchanged.','No framing account affects the reader’s judgment.','Explain the relation rather than stop at a label.','meaning'],['What makes colossal wreck worth analysing?','Magnitude and damage are placed together.','The two words provide an exact archaeological measurement.','Every adjective always creates the same response.','A local verbal tension can support a qualified interpretation.','methods'],['Which paragraph is too generic?','One that names imagery without specifying what this image does.','One that connects emptiness with the preceding boast.','One that qualifies the meaning of survival.','An analytical explanation should be specific to its evidence.','evaluation'],['What would a developed conclusion retain?','The boast is tested, while representation and past consequences need not disappear entirely.','Every reader must deny that power ever existed.','A single device term settles every historical question.','A proportionate judgment includes the evidence’s limits.','argument']],writing:'Turn a device label into an analytical point: explain how the setting tests the boast, connect the relation with enduring power and qualify the effect.',rubric:['Locate a precise choice and explain a relation within its context.','Connect the method’s significance with the actual question.','Qualify the claim without confusing failed endurance with no historical consequences.']}),
make({key:'workshop-05',title:'Evidence-based disagreement and alternative readings',scope:'Macbeth · prediction, deliberation and choice',sources:[F('1/3'),F('1/7')],quote:'If chance will have me king, why, chance may crown me\nWithout my stir.',
cards:[['State a claim that evidence can test','A reading that Macbeth imagines waiting upon chance can use the conditional and modal wording here. It should not become a claim that he never makes a decision anywhere in the play. Specify the scope of the argument before disagreeing with it, so that a rival is not weakened through exaggeration.'],['Give the rival its strongest support','A reading of agency can examine later deliberation and planning; a reading of influence can examine how predictions shape expectations. Use genuine evidence for each instead of inventing a convenient quotation. A disagreement is productive when it explains a tension in the text rather than merely choosing a side.'],['Refine rather than declare anything goes','Judge which account explains the selected moments more fully and what qualification it needs. Prophecy can change the possibilities imagined without removing every choice. Interpretations can differ, but they still depend on accuracy, relevance and an account of the evidence that challenges them.']],details:[['If','A condition opens a possibility rather than a settled rule.'],['may','Modal uncertainty limits a claim of certainty.'],['Without my stir','Inaction is imagined here and needs testing against later conduct.']],people:[['Influence reading','Examines how prediction shapes expectation.'],['Agency reading','Examines deliberation and chosen conduct.'],['Critical judge','Tests both with relevant counter-evidence.']],movement:[['Define','State the claim’s scope fairly.'],['Support','Use the strongest relevant evidence.'],['Challenge','Find a moment that complicates it.'],['Refine','Reach a qualified judgment about the relation.']],challenge:['Which disagreement is fair?','Test an influence reading against later choices without pretending it claims more than it does.','Invent an obviously false rival and dismiss it.','Accept every claim equally because interpretation is personal.','A fair argument tests accurate claims with genuine evidence.','Represent the rival’s scope and evidence before judging it.'],practice:[['What makes a claim testable?','A clear scope that particular moments can support or challenge.','A declaration that contrary evidence is irrelevant.','A label with no connection to the text.','Precision allows a meaningful evidence test.','argument'],['What should a rival receive?','Its strongest relevant textual support.','A deliberately altered quotation.','No evidence because it is not your preferred view.','Critical fairness strengthens the final judgment.','alternatives'],['What does a qualification do?','Adjust the scope of a claim to account for a genuine tension.','Admit that evidence no longer matters.','Guarantee every possible interpretation is correct.','Refinement should explain more of the text accurately.','evaluation']],check:[['What does the modal wording support?','An imagined possibility of kingship without action.','A universal rule that Macbeth never chooses anything.','A direct command to murder every rival.','Grammar limits the inference a phrase can bear.','meaning'],['Which challenge is relevant?','Later deliberation tests a claim of total passivity.','The number of pages disproves any influence.','An invented ending removes all decisions.','Counter-evidence should bear on the claim being assessed.','evidence'],['Which practice is unfair?','Misstate the rival so it becomes easy to dismiss.','Use genuine textual support for both views.','Explain a limit in your own preferred reading.','A weak invented opponent does not test the actual issue.','evaluation'],['What makes a judgment defensible?','Explain how pressures and choices relate through the evidence.','Declare a preference with no reasoning.','Treat disagreement as proof all claims have equal support.','A qualified conclusion follows from the test.','argument']],writing:'Present two readings of Macbeth’s relation to chance and choice. Give each genuine support, test a limitation and reach a qualified judgment.',rubric:['State the rival fairly with a scope the evidence can test.','Use accurate support and relevant counter-evidence for both accounts.','Refine a judgment that explains tension rather than dismissing evidence.']}),
make({key:'workshop-06',title:'Context integrated with textual analysis',scope:'A Christmas Carol · workhouses in an appeal',sources:[C,W],author:'Charles Dickens',textTitle:'A Christmas Carol',textType:'prose',quote:'“And the Union workhouses?” demanded Scrooge. “Are they still in operation?”',
cards:[['Select the fact the passage needs','After the 1834 reform, parishes in England and Wales were grouped into poor law unions administering relief and workhouses. That fact clarifies Scrooge’s institutional reference. It does not prove every form of relief was identical, or provide a reason to include unrelated Victorian inventions in a paragraph about his response to an appeal.'],['Explain the fact through the wording','The collectors ask for help; Scrooge redirects attention to institutions already operating. Connect the contextual reference with that rhetorical action and the force of demanded. Background knowledge becomes analysis when it explains how a particular choice presents responsibility, rather than interrupting the paragraph with a detached history list.'],['Keep the generalisation proportionate','The novella can challenge an inadequate response to need through particular lives and changed conduct. It does not present a complete replacement legislative system, and every contemporary reader need not have agreed. Use context to inform an interpretation while preserving its textual basis and limits.']],details:[['Union workhouses','A recognisable historical reference, not proof every need is met.'],['demanded','The reporting verb gives the institutional question force.'],['still in operation','The reply shifts attention to existing provision rather than a personal donation.']],people:[['Collectors','Appeal for assistance to people in need.'],['Scrooge','Answers through an institutional question.'],['Contextual analyst','Uses a verified fact to explain that response.']],movement:[['Select','Choose one relevant verified fact.'],['Locate','Connect it with the precise reference.'],['Analyse','Explain what the reply does in the exchange.'],['Qualify','Limit claims about institutions, readers and proposals.']],challenge:['Which context use is integrated?','Explain how the poor law reference helps redirect the appeal towards institutions.','List unrelated dates in place of reading the reply.','Assume the institution’s existence proves every person is adequately helped.','A fact earns its place by illuminating a textual action.','Connect the background knowledge with what Scrooge’s reply does.'],practice:[['What makes the historical fact relevant?','It clarifies the institution named in this exchange.','It is old, so it explains any passage automatically.','It supplies a complete biography of the collector.','Relevance depends on the precise textual reference.','context'],['What should follow the fact?','An explanation of how the institutional question presents responsibility.','A list of unrelated reforms with no method analysis.','A guaranteed prediction of every reader’s opinion.','Context should serve the passage-based claim.','methods'],['Which claim exceeds the novella?','It specifies a complete legislative replacement for relief systems.','It can challenge a narrow response to need.','It presents particular people affected by decisions.','A social criticism differs from a detailed policy programme.','limits']],check:[['What does the 1834 fact clarify?','The reference to Union workhouses in England and Wales.','An exact modern benefit entitlement.','The complete experience of every person receiving relief.','Use a fact at the geographic and historical scope it supports.','meaning'],['What makes demanded analytical evidence?','Its force can shape the institutional response within the appeal.','It makes a date irrelevant in all contexts.','Every reporting verb has an identical emotional effect.','A local choice needs explanation in the exchange.','methods'],['Which contextual inference is unsafe?','An operating institution proves every person’s needs adequately met.','Institutions can be named within an argument about duty.','Historical facts can clarify vocabulary.','Availability and adequacy are different claims.','evaluation'],['What should an integrated paragraph retain?','A textual claim developed through relevant context and precise analysis.','Only background facts with no passage discussion.','A statement that all readers necessarily agree.','Context informs rather than replaces an evidence-led argument.','argument']],writing:'Use one verified fact about the poor law unions to analyse Scrooge’s response to the appeal. Connect context with wording and qualify the social claim.',rubric:['Use a verified historical fact with accurate geographic and temporal scope.','Explain how the reference and reporting verb function in the particular exchange.','Keep context subordinate to a qualified textual argument rather than a detached fact list.']}),
make({key:'workshop-07',title:'Introductions that establish a usable thesis',scope:'A Christmas Carol · a developmental opening claim',sources:[C],author:'Charles Dickens',textTitle:'A Christmas Carol',textType:'prose',quote:'secret, and self-contained, and solitary as an oyster.',
cards:[['Answer the question with a direction','For a question about isolation, an introduction might argue that Scrooge’s separation is challenged through new attention to others and changed conduct. That gives the response a route. A list of publication facts or a retelling of the opening may be accurate but does not by itself establish the argument the essay will test.'],['Make the thesis usable rather than total','A claim should identify a relation you can develop through selected moments. It need not assert that Scrooge is always one thing or that every problem is solved at the ending. Leave room for the childhood memory or a harmful decision to complicate the initial account.'],['Keep the opening accountable to evidence','Test whether the planned paragraphs actually develop the proposed thesis. If the evidence leads elsewhere, revise the opening rather than force the text to obey it. An introduction is a working commitment to a relevant argument, not a decorative paragraph exempt from later qualification.']],details:[['self-contained','An opening image can support a claim about separation.'],['developmental direction','The introduction should indicate what changes or is tested.'],['qualified scope','A thesis can be substantial without claiming every moment is identical.']],people:[['Question-focused writer','States a relation that can be argued.'],['Evidence planner','Tests whether selected moments support the route.'],['Revising writer','Adjusts the opening when the argument becomes more precise.']],movement:[['Answer','State a position on the actual question.'],['Direct','Indicate the development the response will test.'],['Plan','Match paragraphs to the proposed relation.'],['Revise','Adjust the thesis to the evidence’s qualifications.']],challenge:['Which opening offers a usable thesis?','Isolation is challenged as Scrooge gains knowledge of others and changes conduct.','The novel was published and has several staves, with no response to the question.','Scrooge is always identical, so no later evidence needs considering.','A usable thesis offers a relevant relation the essay can develop and test.','Ask what argument the planned paragraphs would actually advance.'],practice:[['What should an introduction establish?','A relevant position and direction for the argument.','Every plot event in chronological order.','Only facts that could introduce any essay.','The opening should answer the task rather than delay it.','thesis'],['Why avoid always without testing it?','A total claim may fail to account for complicating moments.','Every qualified claim is automatically weak.','Evidence never needs to affect the opening.','Scope should match what the text can support.','qualification'],['When should the thesis be revised?','When the developed evidence makes its relation more precise.','Never, even if the paragraphs contradict it.','Only to make it longer without changing meaning.','An opening must remain accountable to the argument.','revision']],check:[['What makes a thesis developmental?','It explains a relation that changes or is tested across the text.','It repeats one fixed label with no route.','It includes every biographical date available.','Direction gives later paragraphs a purpose.','meaning'],['Which opening is insufficient by itself?','A publication fact list with no position on the question.','A qualified claim supported by a planned route.','A thesis open to testing by evidence.','Accuracy alone does not establish an argumentative direction.','evaluation'],['What should the paragraph plan do?','Develop or test the relation stated in the opening.','Ignore the opening’s claim entirely.','Force every moment into a known false assertion.','The route should connect the thesis with evidence.','planning'],['What makes revision responsible?','Refine the thesis when evidence reveals a useful qualification.','Hide every contrary moment without explanation.','Assume the first opening must always be preserved unchanged.','A better fit to evidence strengthens the argument.','argument']],writing:'Write an introduction answering a question about isolation in A Christmas Carol. Give it a developmental direction, then test it against a three-point evidence plan and revise one qualification.',rubric:['Answer the actual question through a clear and usable position.','Indicate a developmental route rather than substitute plot or background facts.','Test and refine the thesis through selected evidence and a genuine qualification.']}),
make({key:'workshop-08',title:'Transitions that develop a sustained argument',scope:'A Christmas Carol · recognition, conduct and a tested connection',sources:[C],author:'Charles Dickens',textTitle:'A Christmas Carol',textType:'prose',quote:'He has the power to render us happy or unhappy; to make our service light or burdensome;',
cards:[['Make the next paragraph change the argument','A paragraph on recognising an employer’s influence can lead to a paragraph testing whether later conduct changes. The transition should explain that relation, not merely announce another event. Words such as furthermore or however are useful only when the reasoning actually adds, contrasts or qualifies something.'],['Use an inference as the bridge','For example, recognising the power to affect workers is a step towards responsibility, but later decisions provide a separate test. That distinction bridges two moments without claiming recognition automatically repairs harm. Write the relation before choosing a connective; otherwise a polished linking word can hide disconnected summaries.'],['Check progression rather than only chronology','An essay can move through the text chronologically while each paragraph remains detached. Ask what the second claim develops, tests or revises from the first. A coherent route may include chronology, but its progression is argumentative: the reader should know why this moment is needed next.']],details:[['power to render','The reference can ground a claim about recognised influence.'],['recognition / conduct','A logical distinction creates a bridge to later evidence.'],['connective','Choose a word that accurately describes an already explained relation.']],people:[['First paragraph writer','Establishes a claim from a precise moment.'],['Developing writer','Uses the next moment to add, test or qualify that claim.'],['Reader','Needs the reason for moving from one point to the next.']],movement:[['State','Summarise the first claim precisely.'],['Relate','Name what the next claim changes or tests.'],['Connect','Choose an accurate transition.'],['Review','Check the route is more than a plot sequence.']],challenge:['Which transition develops reasoning?','Recognition of influence matters, but later conduct tests whether that insight changes treatment of others.','Furthermore, another event happens, with no explained relation.','Every chronological step automatically proves a sustained argument.','A transition should state the logical work of the next point.','Identify what is being added, challenged or qualified.'],practice:[['What should precede choosing however?','A genuine contrast or qualification between claims.','A rule that every paragraph must start the same way.','An unrelated plot event.','The connective should describe an actual relation.','logic'],['Why distinguish recognition and conduct?','The next evidence can test whether insight becomes action.','Recognising a problem guarantees complete repair.','Conduct cannot ever change a judgment.','Different claims need different kinds of support.','argument'],['When is chronology insufficient?','When events are listed without explaining how they develop the thesis.','Whenever an essay mentions an earlier scene.','Only when the text has no ending.','Time order is not automatically argumentative progression.','structure']],check:[['What makes a transition substantive?','It explains how the next claim develops or tests the previous one.','It adds a connective to any disconnected sentence.','It substitutes a plot list for the thesis.','A relation needs reasoning, not only a signalling word.','meaning'],['Which bridge is qualified?','Insight can matter while changed conduct remains a separate test.','A single realisation repairs every consequence automatically.','All later evidence is irrelevant once a claim is made.','An argument can distinguish stages without denying either.','logic'],['What should the reader understand?','Why this evidence is needed at this point in the argument.','Only which stave number comes next.','That every paragraph has an impressive opening word.','Coherence concerns the purpose of the sequence.','structure'],['What improves a weak link?','State the relation between the two claims before choosing a connective.','Add longer synonyms without clarifying the relation.','Repeat the same claim with no development.','Clarity in reasoning should guide the expression.','editing']],writing:'Draft a transition from a paragraph on recognising influence to one on later conduct. Explain the logical relation, select a connective and check how it advances a thesis about responsibility.',rubric:['State the precise relation between the claims before selecting a linking word.','Use the next evidence to develop or test the thesis rather than merely add an event.','Distinguish recognition from conduct while maintaining a coherent route.']}),
make({key:'workshop-09',title:'Conclusions that qualify and answer the question',scope:'A Christmas Carol · judgment supported by an argued route',sources:[C],author:'Charles Dickens',textTitle:'A Christmas Carol',textType:'prose',quote:'I will honour Christmas in my heart, and try to keep it all the year.',
cards:[['Return to the question with a developed judgment','A conclusion should answer the actual question in light of the argument already made. It can draw together the relation between promise and later conduct, but should not simply copy the introduction word for word. Explain what the evidence route has allowed the reader to judge more precisely.'],['Qualify without abandoning the claim','Try is a commitment with an acknowledged need for action, not a complete record of future behaviour. If the essay has analysed continuing conduct, the conclusion can distinguish intention from its later support. Qualification should sharpen the claim rather than become a vague statement that anything might mean anything.'],['Do not introduce an unsupported rescue claim','A final sentence should not announce that all social inequality is solved unless the essay and text establish it. Avoid adding a new historical fact that opens another argument without evidence. A proportionate conclusion can be confident about what the analysed choices support and explicit about what they do not prove.']],details:[['try','Distinguish a commitment from a completed record of future conduct.'],['all the year','The proposed scope extends beyond one occasion.'],['developed judgment','The conclusion should use the route already argued, not invent support.']],people:[['Question-focused writer','Returns to the actual issue being answered.'],['Critical summariser','Draws a judgment from the developed evidence.'],['Reader','Can assess the conclusion against what the essay has established.']],movement:[['Return','Name the question the argument answers.'],['Synthesize','Draw together the relation already analysed.'],['Qualify','Match the claim’s scope to its support.'],['Check','Remove a new unsupported assertion.']],challenge:['Which conclusion is proportionate?','The argument can support changed responsibility while distinguishing promises from later conduct.','One promise proves every social inequality is permanently solved.','A new historical claim needs no evidence if it appears at the end.','A conclusion should follow the argument rather than exceed it.','Check what the analysed evidence actually warrants.'],practice:[['What should a conclusion answer?','The actual question through a judgment developed by the essay.','A different question that is easier to answer.','Only whether the writer enjoyed the text.','The ending should complete the response’s argumentative purpose.','focus'],['What makes qualification useful?','It sharpens the scope of the supported judgment.','It declares every claim equally true.','It replaces all reasoning with maybe.','A precise limit can make the answer more convincing.','qualification'],['Which addition should usually be removed?','A new unsupported fact opening an unrelated argument.','A synthesis of evidence already analysed.','A clarified distinction central to the thesis.','The conclusion should not rely on support never developed.','editing']],check:[['What is the limit of a promise as evidence?','It establishes intention, not by itself every later action.','It guarantees complete future conduct without further support.','It has no possible significance to responsibility.','Different claims require appropriate evidence.','meaning'],['What should synthesis do?','Explain the relation the evidence route has established.','Repeat every sentence from the essay in the same order.','Add a fresh invented quotation to settle the issue.','A developed judgment is more than repetition.','argument'],['Which conclusion overreaches?','The promise proves all social problems disappear forever.','Later conduct can support a claim of change.','The text can question narrow self-interest.','Scope should not exceed the evidence presented.','limits'],['What makes the final answer clear?','A precise judgment and qualification tied to the question.','A vague claim that anything could mean anything.','A plot summary unrelated to the thesis.','Clarity follows from the argument’s purpose and support.','expression']],writing:'Write a conclusion to an argument about responsibility. Synthesize the route, distinguish intention from conduct and remove one unsupported final assertion.',rubric:['Answer the actual question through a developed judgment rather than simple repetition.','Qualify the conclusion using distinctions already supported by the essay.','Avoid new unsupported evidence or total claims beyond the text.']}),
make({key:'workshop-10',title:'Editing grammar punctuation and analytical clarity',scope:'Original practice paragraph · sentence boundaries and attribution',sources:[F('1/7')],author:'Crash Course original practice',textTitle:'Macbeth · source for checking attribution',original:true,quote:'Macbeth recognise ambition, this proves Shakespeare is the murderer and every audience agrees.',explorerNote:'Original deliberately flawed practice sentence, not a student submission or a quotation from Macbeth.',sourceNote:'Original deliberately flawed practice writing for editing. No real student data. Check literary attribution against the linked public-domain Macbeth scene; do not treat the model sentence as source wording.',
cards:[['Diagnose distinct kinds of error','The practice sentence has a subject–verb disagreement, a comma splice and unsupported attribution. Correct Macbeth recognises, then decide how its two independent clauses should be linked or separated. Punctuation repairs expression, but it cannot by itself make the claim that Shakespeare is the murderer accurate.'],['Repair reasoning as well as grammar','A clearer claim could distinguish the character’s recognition from the poet’s construction: Shakespeare presents Macbeth recognising ambition, but that does not prove the motive has been overcome. This is original model analysis, not a quotation. Replace the universal audience claim with a supported and qualified possibility.'],['Preserve source evidence during editing','Edit your own sentence, attribution and relation between claims. Do not change a verified source quotation silently to make it sound smoother. A meaningful edit improves accuracy and clarity; increasing word length or adding a technical term without explanation does not repair a logical gap.']],details:[['recognise','The singular subject needs recognises in this sentence.'],['comma splice','Two independent clauses need a suitable boundary or conjunction.'],['Shakespeare is the murderer','The claim confuses author and character and requires a substantive correction.']],people:[['Practice writer','Has a deliberately flawed original sentence to diagnose.'],['Editor','Separates grammatical, attribution and reasoning errors.'],['Source checker','Keeps actual Shakespearean words distinct from the practice model.']],movement:[['Diagnose','Identify grammar and punctuation separately.'],['Correct','Repair subject–verb agreement and clause boundaries.'],['Reconsider','Fix attribution and unsupported certainty.'],['Verify','Check your own wording without falsifying the source.']],challenge:['Which edit is substantive?','Repair grammar and clause boundaries, then correct author–character confusion and unsupported certainty.','Only replace proves with a longer synonym while retaining the false claim.','Silently rewrite the source quotation to fit a preferred thesis.','Clear expression and accurate reasoning require separate checks.','Ask whether the edited claim is true as well as grammatically complete.'],practice:[['What agreement does the practice subject require?','Macbeth recognises.','Macbeth recognise in this singular statement.','No verb because all analysis is a quotation.','Subject and verb should agree in the writer’s own sentence.','grammar'],['What is a comma splice here?','Independent clauses joined only by a comma.','Any comma appearing inside a quotation.','A sentence that contains a poetic image.','Identify clause structure before choosing a repair.','punctuation'],['Which error cannot punctuation alone fix?','Confusing Shakespeare with the fictional murderer.','A missing full stop between clauses.','An unclear comma boundary.','Attribution and reasoning need substantive correction.','accuracy']],check:[['What is the status of the displayed sentence?','Original deliberately flawed practice writing, not a source quotation or real student work.','An exact quotation from Shakespeare.','A verified pupil submission published without consent.','The model’s label distinguishes its purpose and origin.','meaning'],['Which repair addresses agreement?','Use recognises with the singular Macbeth.','Leave the mismatch because analysis has no grammar rules.','Change the source words without signalling it.','Edit the writer’s sentence accurately.','grammar'],['Which attribution is accurate?','Shakespeare constructs Macbeth as a character who considers ambition.','Shakespeare literally commits the fictional murder.','Every character’s speech is the author’s unmediated confession.','Keep author, character and critic distinct.','accuracy'],['What should a final clarity check ask?','Does the corrected sentence make a supported, qualified claim with clear relations?','Does it contain longer words regardless of meaning?','Can a technical label replace every explanation?','Editing should improve reasoning and expression together.','editing']],writing:'Rewrite the original practice sentence, identifying a grammar repair, a punctuation repair and a substantive correction. Then edit one sentence of your own analysis without altering verified quoted words.',rubric:['Diagnose and repair subject–verb agreement and independent-clause boundaries.','Correct attribution and unsupported certainty as substantive reasoning issues.','Keep source wording accurate while making the writer’s own analysis clear.']}),
make({key:'workshop-11',title:'Paper 1 rehearsal and feedback conference',scope:'Two original extract-to-whole tasks · Macbeth and A Christmas Carol',minutes:120,sources:[F('1/7'),F('2/1'),C],quote:'He’s here in double trust:',
cards:[['Prepare a method for both texts','Use the brief trust reference to practise moving from a precise choice to a wider claim. The independent rehearsal supplies different Macbeth and Carol passages, so plan a method of reading rather than one fixed essay. Both responses should address the supplied detail and develop it through relevant knowledge of the whole text.'],['Rehearse with explicit conditions','The workspace contains two original tasks, not a past paper or an official mark scheme. Aim for about 105 minutes for both, including planning and checking; timing is advisory, not enforced. Label both responses. Full readings and access arrangements remain matters to calibrate with a teacher; the app cannot monitor external resources.'],['Use a real feedback conversation after submission','After preserving the first attempt, use the criteria and conference questions for self-review or discussion with a teacher who actually reads the writing. Identify one evidence strength, one gap and one priority. No teacher review is implied by clicking Submit; later revisions remain separate from the original response.']],details:[['Extract first','Read the supplied situation before choosing wider evidence.'],['Whole-text connection','Develop the passage-based claim rather than append an unrelated scene.'],['Conference priority','Choose a specific change from the actual response and real feedback if available.']],people:[['Rehearsing writer','Produces two labelled original responses under advisory conditions.'],['Human reviewer','Can assess the actual work when a real review takes place.'],['Revising writer','Uses an identified priority without erasing the first attempt.']],movement:[['Prepare','Read each fresh task and passage.'],['Respond','Develop extract-to-whole arguments for both texts.'],['Review','Use actual criteria and conference questions after submission.'],['Revise','Save a separate response addressing one priority.']],challenge:['Which rehearsal claim is honest?','It records two original practice responses for later review, not an official mark or proof of exam readiness.','Completing the knowledge questions supplies an examiner’s essay grade.','A saved response proves a teacher has already attended a conference.','Practice records and actual reviewed attainment are different forms of evidence.','Distinguish what the workspace records from a review that must actually happen.'],practice:[['What should each response connect?','The supplied passage’s methods with relevant whole-text evidence.','An unrelated memorised essay with no passage analysis.','Only a list of every scene in order.','An extract-to-whole argument needs an explained relation.','structure'],['What is the suggested overall budget?','About 105 minutes, advisory and not enforced.','An automatic compulsory deadline for every learner.','A guarantee of an official grade at the end.','The conditions should be described accurately.','conditions'],['What makes a conference priority usable?','A specific gap in the actual response and a concrete next edit.','A fabricated teacher comment.','Only a predicted grade with no evidence.','Feedback should point to an inspectable improvement.','review']],check:[['What distinguishes the rehearsal from an official paper?','The tasks are original practice and no official mark is assigned.','The app is an official AQA examiner.','Every saved response has been specialist graded.','Practice conditions must not be misrepresented.','meaning'],['What should wider evidence do?','Develop or test the passage-based answer to the actual question.','Replace all close reading with unrelated context.','Prove that any remembered detail is relevant.','Selection should serve the response’s focus.','argument'],['What is preserved during supported revision?','The original first submitted response.','Only the newest words with the initial attempt erased.','A guaranteed top-grade judgment.','Versions distinguish independent performance and later support.','versions'],['Which review is real?','Self-review or a discussion with a person who actually reads the response.','A conference assumed complete because a button was clicked.','A mark invented from the selected-response score.','A record should not claim a human action that has not happened.','review']],writing:'Practise a passage-to-whole plan, then complete both tasks in the independent rehearsal. Use the conference prompts only after preserving the first attempt.',rubric:['Answer both original questions with relevant extract-to-whole arguments in the selected texts.','Analyse precise choices and accurate wider references, using context where it explains a detail.','Review coherence, qualification and Standard English through actual writing rather than knowledge scores.'],sourceNote:'Original rehearsal tasks; not an official paper or mark scheme. Supplied Macbeth2.1 and CarolStave2 passages use underlying public-domain wording. Full scene/stave links provided; line wrapping and typographic punctuation may differ by edition. No source editorial commentary copied. Timing advisory; writing unmarked; conference requires actual self-review or a real reader.',extra:{independentWriting:true,independentTaskType:'paper1-rehearsal',independentTaskLabel:'Original Paper 1 format rehearsal with two supplied public-domain passages; not an official examination paper.',independentIntro:'Write both labelled responses. Aim for about 105 minutes including planning and checking. Timing is advisory, not enforced. Use the supplied extracts and your knowledge of both whole texts.',independentPrompt:'TASK 1: Starting with the Macbeth passage, explore how Shakespeare presents uncertain perception. Analyse this passage and relevant moments elsewhere in the play. TASK 2: Starting with the A Christmas Carol passage, explore how Dickens presents an employer’s influence on other people. Analyse this passage and relevant moments elsewhere in the novella. Label Task 1 and Task 2.',independentExtractLabel:'Two public-domain extracts · original practice tasks',independentExtract:paper1Extracts,feedbackConference:['Where does each response move from exact wording to a relevant whole-text claim? Identify a real strength.','Which reference or explanation is inaccurate, unsupported or insufficiently linked to the question? Choose one actual gap.','What specific edit will you make next, and how will you check it against the source or real feedback?']}}),
make({key:'workshop-12',title:'Paper 2 rehearsal and feedback conference',scope:'Original modern text, anthology and unfamiliar-poetry rehearsal',minutes:150,sources:[A,'https://www.concordtheatricals.com/p/12689/an-inspector-calls',readings13.leisure.url,readings13.daffodils.url],author:'William Blake',textTitle:'Power and Conflict anthology',textType:'poem',quote:'In every voice, in every ban,\nThe mind-forged manacles I hear:',
cards:[['Prepare the different evidence requirements','A whole-play argument, an anthology comparison and unfamiliar-poem analysis do not use evidence in identical ways. Practise a method-level point with the brief London reference, then read the independent tasks carefully. The rehearsal supplies Ozymandias and a different complete unfamiliar pair; it does not reproduce the protected modern play or every assigned poem.'],['Attempt the original sections honestly','Choose one modern-text question, complete the anthology comparison, then answer the single-poem and paired-poem tasks. Aim for about 135 minutes overall, with roughly 35 minutes for the single unfamiliar poem and 10 for its comparison; these are advisory, not enforced. If either unfamiliar text is already known, report the attempt as practice rather than genuinely unseen.'],['Conference from the actual four responses','After first submission, use the criteria and conference prompts to compare evidence use across the sections. A self-review can identify a specific priority; an actual teacher review requires someone to read the writing. No automatic mark or readiness claim is made. Preserve the first response and save later revisions separately.']],details:[['Section-specific evidence','A whole-play claim differs from a supplied-poem comparison or fresh close reading.'],['Partner selection','Choose a second anthology poem because it serves the actual focus.'],['Review across tasks','Compare the quality of reasoning in the actual labelled responses.']],people:[['Rehearsing writer','Completes the selected modern task and the three required poetry tasks.'],['Reviewer','Examines actual writing rather than inferring attainment from activity completion.'],['Revising writer','Chooses a priority and preserves the first attempt separately.']],movement:[['Read','Identify each section’s specific task and evidence.'],['Respond','Label the modern, anthology, single-poem and comparison answers.'],['Confer','Use real strengths and gaps after first submission.'],['Revise','Save a separate change and plan later practice.']],challenge:['Which evidence plan fits the rehearsal?','Distinguish whole-play references, the supplied anthology poem and fresh single/pair analysis.','Paste the same memorised paragraph into every section.','Assume all four tasks require identical evidence and method.','The task type changes what evidence the argument must explain.','Read what each section asks rather than transfer one fixed answer.'],practice:[['What choice is offered in the modern section?','Choose one of two original whole-play questions.','Answer neither because the poem section replaces it.','Treat a supplied protected script passage as reproduced here.','The original rehearsal retains a modern-text question choice without copying the play.','conditions'],['What does anthology selection require?','A relevant second assigned poem connected to the actual focus.','Only the poem with the longest remembered quotation.','A claim every pair must have identical meanings.','Partner choice should support a reasoned comparison.','selection'],['What should review compare?','Actual evidence use and reasoning across the labelled responses.','Only the number of words as a guaranteed grade.','A fabricated examiner’s prediction.','Review needs the work itself and specific criteria.','review']],check:[['What must be completed after choosing the modern question?','The anthology comparison, single-poem analysis and paired-poem comparison.','Only one optional poem instead of all remaining tasks.','An official examiner mark created by the app.','The original rehearsal contains distinct required poetry responses.','meaning'],['When is an unfamiliarity claim inaccurate?','When the supplied poem is already known and the attempt is described as genuinely unseen.','When a reader admits prior familiarity.','When a later response is called revision.','Describe the conditions of performance honestly.','assessment'],['What does submission establish?','A preserved practice response, not an official mark or a completed teacher review.','Automatic exam readiness across every skill.','Proof a specialist has approved every sentence.','Activity records do not replace actual evaluation of writing.','limits'],['What makes a next-step priority concrete?','Identify a specific gap in one response and an edit or practice to address it.','Only say improve everything with no evidence.','Invent feedback and a predicted grade.','A useful priority points to an inspectable action.','review']],writing:'Read the independent rehearsal’s four tasks, choose one modern-text question and complete all required poetry responses. Use the conference prompts after preserving the first submission.',rubric:['Answer the chosen modern question and all required poetry tasks with accurate, relevant evidence.','Analyse precise methods and sustain comparisons without forcing identical meanings or inventing biography.','Use actual review of coherence and expression to identify a concrete next step; no automatic mark is assigned.'],sourceNote:'Original Paper2-format practice, not an official paper or mark scheme. Complete underlying public-domain Ozymandias, Leisure and I Wandered Lonely as a Cloud supplied; exact poem sources and versions recorded in reading-texts13.js. Modern Inspector and other assigned anthology poems are not reproduced; authorised texts required for checking after the attempt. Firstresponse preserved, timing advisory, actual written review outstanding.',extra:{independentWriting:true,independentTaskType:'paper2-rehearsal',independentTaskLabel:'Original Paper 2 format rehearsal: choose one modern question, then complete all three poetry tasks.',independentIntro:'Label all four responses. Aim for about 135 minutes overall; suggested unfamiliar-poetry budgets are 35 minutes for Task 3 and 10 for Task 4. Timing is advisory, not enforced. Prior familiarity with either fresh poem means this is practice, not a genuinely unseen encounter.',independentPrompt:'TASK 1 — choose ONE: A. How does Priestley present accepting responsibility in An Inspector Calls? OR B. How does Priestley present divisions within the Birling family? Use whole-play references. TASK 2: Compare how poets present the limits of power in the supplied Ozymandias and one other Power and Conflict poem of your choice. TASK 3: How does Davies use language and organisation to present attention to the world in Leisure? TASK 4: Compare how methods in Leisure and I Wandered Lonely as a Cloud make attention to nature significant. Label Task 1, Task 2, Task 3 and Task 4.',independentExtractLabel:'Supplied public-domain anthology poem followed by two complete unfamiliar-practice poems',independentExtract:`TASK 2 · Ozymandias — Percy Bysshe Shelley\n\n${ozymandias}\n\nTASKS 3–4 · Complete poems\n\n${whole13('leisure','daffodils')}`,feedbackConference:['Which response best explains a method through accurate evidence? Identify the actual strength, not only its length.','Where does an argument become a plot list, a device label or two disconnected summaries? Locate one concrete example.','Which source check, revision or later practice will address that gap? Distinguish self-review from feedback a teacher has actually given.']}})
];
